# apü client runtime for Python (standard library only; Python ≥ 3.11). Embedded into every module
# generated by `apue-types --lang python`; the generated part below adds the API's types and methods.
# HTTP/1.1 over TLS with keep-alive (http.client). One connection per client, one call at a time: not
# thread-safe; a call made while a stream or download is still being read closes that response (a
# resumable stream or a download then resumes). Use one client per thread for concurrent calls.
# Covers: unary calls (GET ?i= for cacheable reads, QUERY when the URL would be too long — POST where
# QUERY is rejected —, POST otherwise, Idempotency-Key for non-safe calls), retries (connection loss,
# 429/503 with Retry-After, retryable 409), server streams resumed after a lost connection (CHECKPOINT
# tokens, `apue-resume`, items since the checkpoint skipped: exactly once), client and bidi streams,
# pipelined batches (`client.batch()`: refs, per-call keys, lanes), compressed responses (gzip; zstd
# with Python ≥ 3.14's compression.zstd; decoded incrementally, frame by frame), client-side input
# validation (the manifest's JSON Schema; problems shaped like the server's), RFC 9457 problems,
# deadlines, bytes in messages (BLOB frames), uploads for bytes/file inputs (one request each, not
# resumed), t.download() outputs (resumed with Range + If-Range).
# Not covered: full duplex — http.client speaks HTTP/1.1 only and sends the whole request body before
# it reads the response (no HTTP/2 or WebSocket in the standard library), so bidi streams are half
# duplex: all inputs, then all outputs. Brotli (not in the standard library). Resumable uploads.
# Patterns: JavaScript RegExp semantics are translated (anchors, `.`, \d \w \s \b, UTF-16 code units
# without the u/v flag); patterns that can't be translated exactly (\p{…}, back-references, inline
# modifiers, v-flag set operations, variable-length lookbehind) and case-insensitive matching that
# involves non-ASCII characters are left to the server (with an ApueWarning for untranslatable
# patterns), which validates every input anyway.
from __future__ import annotations

import email.utils
import hashlib
import http.client
import json
import math
import random
import re
import ssl
import struct
import time
import urllib.parse
import uuid
import warnings
import zlib
from typing import Any, BinaryIO, Generic, Iterable, Iterator, Optional, TypeVar, Union

try:  # Python ≥ 3.14 (PEP 784), when built with libzstd
    from compression import zstd as _zstd
except ImportError:  # pragma: no cover - depends on the Python build
    _zstd = None

STREAM_JSON = "application/vnd.apue.frames"
ACCEPT = "application/vnd.apue.frames, application/json;q=0.9, application/problem+json;q=0.8"
ACCEPT_ENCODING = "zstd, gzip" if _zstd is not None else "gzip"
MAX_GET_URL = 2048
MAX_FRAME = 16 * 1024 * 1024  # per frame, like the TypeScript client
MAX_BLOBS = 64 * 1024 * 1024  # bytes per message
MSG, END, BLOB, HEARTBEAT, CHECKPOINT = 0x00, 0x01, 0x02, 0x03, 0x04
FLAG_LAST = 0x02
BLOB_CHUNK = 64 * 1024
QUERY_REJECTED = (400, 403, 405, 501)  # intermediaries without QUERY support (Envoy, CloudFront, Akamai)
PROBLEMS = "https://apue.dev/problems/"

T = TypeVar("T")


class ApueError(Exception):
    """An RFC 9457 problem: the call failed with `status` (HTTP semantics)."""

    def __init__(self, status: int, problem: Optional[dict] = None):
        self.status = status
        self.problem = problem or {}
        self.type = self.problem.get("type", "about:blank")
        self.title = self.problem.get("title", "Error")
        self.detail = self.problem.get("detail")
        self.retryable = bool(self.problem.get("retryable", False))
        self.fields: Optional[list] = self.problem.get("fields")
        super().__init__(f"{status} {self.title}" + (f": {self.detail}" if self.detail else ""))


class _Truncated(ApueError):
    """The response body ended before its END frame: a lost connection (resumable)."""


class ApueWarning(UserWarning):
    """Something the client can't do exactly as the TypeScript client would (e.g. a pattern it can't check)."""


def _error(status: int, title: str, detail: str, kind: Optional[str] = None, cls: type = ApueError) -> ApueError:
    problem: dict = {"title": title, "status": status, "detail": detail}
    if kind:
        problem["type"] = PROBLEMS + kind
    return cls(status, problem)


def _malformed(detail: str) -> ApueError:
    return _error(502, "Malformed Stream", detail, "malformed-stream")


# ---- JSON ---------------------------------------------------------------------------------------

def _js_number(n: float) -> str:
    """ECMAScript Number::toString for a finite float (shortest round trip, JS exponent rules)."""
    if n == 0:
        return "0"
    if n < 0:
        return "-" + _js_number(-n)
    mantissa, _, exponent = repr(n).partition("e")
    whole, _, fraction = mantissa.partition(".")
    digits = whole + fraction
    point = len(whole) + (int(exponent) if exponent else 0)
    stripped = digits.lstrip("0")
    point -= len(digits) - len(stripped)
    digits = stripped.rstrip("0") or "0"
    k = len(digits)
    if k <= point <= 21:
        return digits + "0" * (point - k)
    if 0 < point <= 21:
        return digits[:point] + "." + digits[point:]
    if -6 < point <= 0:
        return "0." + "0" * -point + digits
    e = point - 1
    return (digits if k == 1 else digits[0] + "." + digits[1:]) + "e" + ("+" if e >= 0 else "-") + str(abs(e))


def _number(n: Any) -> str:
    if isinstance(n, bool):
        return "true" if n else "false"
    if isinstance(n, int):
        return str(n)
    if not math.isfinite(n):
        raise ValueError("NaN and infinities are not JSON")
    return _js_number(float(n))


def canonical_json(value: Any) -> str:
    """JSON with sorted keys and ES number formatting — RFC 8785 for the values apü sends (cache-friendly GET URLs)."""

    def encode(v: Any) -> str:
        if v is None or isinstance(v, bool):
            return json.dumps(v)
        if isinstance(v, (int, float)):
            return _number(v)
        if isinstance(v, str):
            return json.dumps(v, ensure_ascii=False)
        if isinstance(v, (list, tuple)):
            return "[" + ",".join(encode(x) for x in v) + "]"
        if isinstance(v, dict):
            keys = sorted(v.keys(), key=lambda k: k.encode("utf-16-be"))
            return "{" + ",".join(json.dumps(k, ensure_ascii=False) + ":" + encode(v[k]) for k in keys if v[k] is not _ABSENT) + "}"
        raise TypeError(f"not JSON-serialisable: {type(v).__name__}")

    return encode(value)


_ABSENT = object()


# ---- frames and bytes ---------------------------------------------------------------------------

def _frame(kind: int, payload: bytes = b"", lane: int = 0, flags: int = 0) -> bytes:
    return struct.pack(">BBHI", kind, flags, lane, len(payload)) + payload


def _split_message(value: Any) -> tuple[Any, list[bytes]]:
    """bytes → {"$blob": k} (sent as BLOB frames first); look-alikes escaped as {"$lit": …}."""
    blobs: list[bytes] = []

    def extract(v: Any) -> Any:
        if isinstance(v, (bytes, bytearray, memoryview)):
            blobs.append(bytes(v))
            return {"$blob": len(blobs) - 1}
        if isinstance(v, (list, tuple)):
            return [extract(x) for x in v]
        if isinstance(v, dict):
            if len(v) == 1 and next(iter(v)) in ("$blob", "$lit"):
                return {"$lit": v}
            return {k: extract(x) for k, x in v.items()}
        return v

    return extract(value), blobs


def _restore(value: Any, blobs: list[bytes], used: set) -> Any:
    if isinstance(value, list):
        return [_restore(x, blobs, used) for x in value]
    if not isinstance(value, dict):
        return value
    if len(value) == 1 and "$lit" in value:
        return value["$lit"]
    if len(value) == 1 and "$blob" in value:
        index = value["$blob"]
        if not isinstance(index, int) or isinstance(index, bool) or not 0 <= index < len(blobs) or index in used:
            raise _malformed(f"invalid blob reference {index!r}")
        used.add(index)
        return blobs[index]
    return {k: _restore(x, blobs, used) for k, x in value.items()}


class _Blobs:
    """Collects BLOB frames for the next MSG (per lane) and resolves its {"$blob": k} references."""

    def __init__(self) -> None:
        self._done: list[bytes] = []
        self._chunks: list[bytes] = []
        self._size = 0

    def push(self, flags: int, payload: bytes) -> None:
        self._size += len(payload)
        if self._size > MAX_BLOBS:
            raise _malformed(f"more than {MAX_BLOBS} bytes of blobs for one message")
        self._chunks.append(payload)
        if flags & FLAG_LAST:
            self._done.append(b"".join(self._chunks))
            self._chunks = []

    def resolve(self, value: Any) -> Any:
        if self._chunks:
            raise _malformed("message inside an unfinished blob")
        used: set = set()
        value = _restore(value, self._done, used)
        if len(used) != len(self._done):
            raise _malformed("unreferenced blobs")
        self._done, self._size = [], 0
        return value


def _message_frames(value: Any) -> Iterator[bytes]:
    json_part, blobs = _split_message(value)
    for blob in blobs:
        if not blob:
            yield _frame(BLOB, b"", 0, FLAG_LAST)
        for offset in range(0, len(blob), BLOB_CHUNK):
            end = min(offset + BLOB_CHUNK, len(blob))
            yield _frame(BLOB, blob[offset:end], 0, FLAG_LAST if end == len(blob) else 0)
    yield _frame(MSG, json.dumps(json_part, separators=(",", ":"), ensure_ascii=False).encode())


def _transfers(schema: Any, kind: str) -> bool:
    """Whether a JSON Schema has `x-apue-transfer: kind` (or any of the given kinds) anywhere."""
    if isinstance(schema, dict):
        if schema.get("x-apue-transfer") in kind.split("|"):
            return True
        return any(_transfers(v, kind) for v in schema.values())
    if isinstance(schema, list):
        return any(_transfers(v, kind) for v in schema)
    return False


def _map(schema: dict, value: Any, kinds: tuple, fn) -> Any:
    """Applies fn at every position whose schema has x-apue-transfer in kinds (schema-directed)."""
    if value is None:
        return value
    if schema.get("x-apue-transfer") in kinds:
        return fn(value, schema["x-apue-transfer"])
    if "anyOf" in schema:
        branch = next((b for b in schema["anyOf"] if b.get("type") != "null"), None)
        return _map(branch, value, kinds, fn) if branch else value
    if schema.get("type") == "array" and isinstance(value, (list, tuple)):
        return [_map(schema.get("items", {}), x, kinds, fn) for x in value]
    if schema.get("type") == "object" and isinstance(value, dict):
        props = schema.get("properties", {})
        return {k: (_map(props[k], x, kinds, fn) if k in props else x) for k, x in value.items()}
    return value


# ---- client-side validation (the JSON Schema subset apü emits) ----------------------------------

_LINE_END = "\\n\\r\\u2028\\u2029"  # JS line terminators, as Python class content
_SPACE = "\\t\\n\\x0b\\x0c\\r \\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000\\ufeff"  # JS \s
_WORD = "A-Za-z0-9_"  # JS \w (ASCII, unlike Python's)
_SHORTHAND = {"d": "0-9", "w": _WORD, "s": _SPACE}
_BOUNDARY = f"(?:(?<=[{_WORD}])(?![{_WORD}])|(?<![{_WORD}])(?=[{_WORD}]))"
_NOT_BOUNDARY = f"(?:(?<=[{_WORD}])(?=[{_WORD}])|(?<![{_WORD}])(?![{_WORD}]))"
_QUANTIFIER = re.compile(r"\{\d+(?:,\d*)?\}")
_HEX = "0123456789abcdefABCDEF"
_PATTERNS: dict = {}


class _Untranslatable(Exception):
    pass


def _units(text: str) -> str:
    """Astral characters as UTF-16 surrogate pairs: what a JavaScript RegExp without u/v sees."""
    if all(ord(c) < 0x10000 for c in text):
        return text
    out = []
    for c in text:
        code = ord(c)
        if code > 0xFFFF:
            code -= 0x10000
            out.append(chr(0xD800 + (code >> 10)) + chr(0xDC00 + (code & 0x3FF)))
        else:
            out.append(c)
    return "".join(out)


def _utf16_length(text: str) -> int:
    """JavaScript's String#length (minLength/maxLength count UTF-16 code units)."""
    return len(text) + sum(1 for c in text if ord(c) > 0xFFFF)


class _Translator:
    """JavaScript RegExp source → an equivalent Python `re` pattern, or _Untranslatable."""

    def __init__(self, source: str, flags: str):
        self.unicode = "u" in flags or "v" in flags
        self.sets = "v" in flags
        self.src = source if self.unicode else _units(source)
        self.dot = "[\\s\\S]" if "s" in flags else f"[^{_LINE_END}]"
        self.start = f"(?:\\A|(?<=[{_LINE_END}]))" if "m" in flags else "\\A"
        self.end = f"(?=[{_LINE_END}]|\\Z)" if "m" in flags else "\\Z"  # Python's `$` also matches before a final \n
        self.named = re.search(r"\(\?<(?![=!])", self.src) is not None
        self.non_ascii = False  # a non-ASCII character in the pattern (case folding differs: see _pattern_deferred)

    def lit(self, ch: str) -> str:
        """A literal character, escaped so that it means itself anywhere (also inside a class)."""
        self.non_ascii = self.non_ascii or not ch.isascii()
        return ch if ch.isascii() and ch.isalnum() else f"\\U{ord(ch):08x}"

    def translate(self) -> str:
        src, out, i = self.src, [], 0
        while i < len(src):
            c = src[i]
            if c == "\\":
                fragment, i = self.escape(i + 1, False)
                out.append(fragment)
                continue
            if c == "[":
                fragment, i = self.char_class(i + 1)
                out.append(fragment)
                continue
            if c == "(" and src.startswith("(?", i):
                prefix = next((p for p in ("(?:", "(?=", "(?!", "(?<=", "(?<!") if src.startswith(p, i)), None)
                if prefix:
                    out.append(prefix)
                    i += len(prefix)
                    continue
                close = src.find(">", i)
                name = src[i + 3:close] if src.startswith("(?<", i) and close > 0 else ""
                if not name.isidentifier():
                    raise _Untranslatable("inline modifiers or an unusual group name")
                out.append(f"(?P<{name}>")
                i = close + 1
                continue
            if c == "{":
                quantifier = _QUANTIFIER.match(src, i)
                if quantifier:
                    out.append(quantifier.group())
                    i = quantifier.end()
                    continue
                out.append("\\{")  # a literal brace (Annex B); Python would read {,n} as a quantifier
            elif c in "}]":
                out.append("\\" + c)
            elif c == ".":
                out.append(self.dot)
            elif c == "^":
                out.append(self.start)
            elif c == "$":
                out.append(self.end)
            elif c in "()*+?|":
                out.append(c)
            else:
                out.append(self.lit(c))
            i += 1
        return "".join(out)

    def escape(self, i: int, in_class: bool) -> tuple[str, int]:
        src = self.src
        if i >= len(src):
            raise _Untranslatable("trailing backslash")
        c = src[i]
        if c in "dws":
            return (_SHORTHAND[c] if in_class else f"[{_SHORTHAND[c]}]"), i + 1
        if c in "DWS":  # (inside a class: handled by char_class)
            return f"[^{_SHORTHAND[c.lower()]}]", i + 1
        if c == "b":
            return ("\\x08" if in_class else _BOUNDARY), i + 1
        if c == "B":
            if in_class:
                raise _Untranslatable("\\B inside a class")
            return _NOT_BOUNDARY, i + 1
        if c in "123456789" or (c == "k" and (self.unicode or self.named)):
            # JS matches a group that didn't participate as empty, Python fails: not equivalent.
            raise _Untranslatable("back-reference")
        if c == "0":
            if i + 1 < len(src) and src[i + 1].isdigit():
                raise _Untranslatable("legacy octal escape")
            return "\\x00", i + 1
        if c == "c":
            if i + 1 < len(src) and src[i + 1].isascii() and src[i + 1].isalpha():
                return self.lit(chr(ord(src[i + 1]) % 32)), i + 2
            raise _Untranslatable("\\c without a letter")
        if c == "x" and len(src) >= i + 3 and all(h in _HEX for h in src[i + 1:i + 3]):
            return self.lit(chr(int(src[i + 1:i + 3], 16))), i + 3
        if c == "u":
            if self.unicode and src.startswith("{", i + 1):
                close = src.find("}", i)
                digits = src[i + 2:close] if close > 0 else ""
                if not digits or any(h not in _HEX for h in digits) or int(digits, 16) > 0x10FFFF:
                    raise _Untranslatable("invalid \\u{…}")
                return self.lit(chr(int(digits, 16))), close + 1
            if len(src) >= i + 5 and all(h in _HEX for h in src[i + 1:i + 5]):
                code, i = int(src[i + 1:i + 5], 16), i + 5
                trail = src[i + 2:i + 6] if src.startswith("\\u", i) else ""
                if self.unicode and 0xD800 <= code < 0xDC00 and len(trail) == 4 and all(h in _HEX for h in trail) and 0xDC00 <= int(trail, 16) < 0xE000:
                    code, i = 0x10000 + ((code - 0xD800) << 10) + (int(trail, 16) - 0xDC00), i + 6
                return self.lit(chr(code)), i
        if c in "pP" and self.unicode:
            raise _Untranslatable("Unicode property escape")
        if c == "q" and self.sets:
            raise _Untranslatable("string literal in a class")
        controls = {"t": "\t", "n": "\n", "v": "\v", "f": "\f", "r": "\r"}
        if c in controls:
            return self.lit(controls[c]), i + 1
        return self.lit(c), i + 1  # identity escape (also \A, \Z …: plain letters in JavaScript)

    def char_class(self, i: int) -> tuple[str, int]:
        src = self.src
        negate = src.startswith("^", i)
        i += 1 if negate else 0
        if src.startswith("]", i):
            return ("[\\s\\S]" if negate else "(?!)"), i + 1  # JS [^] and []
        parts, negated = [], []  # negated: \D \W \S, whose JS sets Python can't put inside a class
        while i < len(src) and src[i] != "]":
            c = src[i]
            if c == "\\" and i + 1 < len(src) and src[i + 1] in "DWS":
                negated.append(_SHORTHAND[src[i + 1].lower()])
                i += 2
                continue
            if c == "\\":
                fragment, i = self.escape(i + 1, True)
                parts.append(fragment)
                continue
            if self.sets and (c == "[" or src.startswith("--", i) or src.startswith("&&", i)):
                raise _Untranslatable("v-flag set operations")
            parts.append("-" if c == "-" else self.lit(c))
            i += 1
        if i >= len(src):
            raise _Untranslatable("unterminated class")
        positive = "".join(parts)
        if not negated:
            return "[" + ("^" if negate else "") + positive + "]", i + 1
        if not negate:  # [P\S] = P ∪ ¬S
            return "(?:" + "|".join(([f"[{positive}]"] if positive else []) + [f"[^{s}]" for s in negated]) + ")", i + 1
        # [^P\S] = ¬P ∩ S: one character in every S and not in P
        checks = ([f"(?![{positive}])"] if positive else []) + [f"(?=[{s}])" for s in negated[:-1]]
        return "(?:" + "".join(checks) + f"[{negated[-1]}])", i + 1


def _js_regex(source: str, flags: str) -> Optional[re.Pattern]:
    """The compiled translation of a JavaScript RegExp, or None (with a warning) if it has none."""
    return _compiled(source, flags)[0]


def _compiled(source: str, flags: str) -> tuple[Optional[re.Pattern], bool]:
    key = (source, flags)
    if key not in _PATTERNS:
        compiled, non_ascii = None, False
        if set(flags) <= set("dimsuv") and not ("u" in flags and "v" in flags):
            try:
                with warnings.catch_warnings():
                    warnings.simplefilter("error")  # FutureWarning: Python may read this class differently later
                    translator = _Translator(source, flags)
                    compiled = re.compile(translator.translate(), re.IGNORECASE if "i" in flags else 0)
                    non_ascii = translator.non_ascii
            except (_Untranslatable, re.error, Warning, ValueError, OverflowError, RecursionError):
                compiled = None
        if compiled is None:
            warnings.warn(f"apü: the pattern /{source}/{flags} is not checked in Python (the server checks it)", ApueWarning, stacklevel=3)
        _PATTERNS[key] = (compiled, non_ascii)
    return _PATTERNS[key]


def _pattern_deferred(source: str, flags: str, value: str) -> bool:
    """Whether a pattern check is left to the server: no exact translation, or case-insensitive matching
    that involves non-ASCII characters (JavaScript and Python fold their case differently)."""
    compiled, non_ascii = _compiled(source, flags)
    return compiled is None or ("i" in flags and (non_ascii or not value.isascii()))


def _pattern_ok(source: str, flags: str, value: str) -> bool:
    if _pattern_deferred(source, flags, value):
        return True
    compiled = _compiled(source, flags)[0]
    return compiled.search(value if "u" in flags or "v" in flags else _units(value)) is not None


def _type_of(value: Any) -> str:
    """JavaScript's view of a value's type, as the server's messages name it."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, (list, tuple)):
        return "array"
    return "object"


def _format_path(path: list) -> str:
    out = ""
    for segment in path:
        out = f"{out}[{segment}]" if isinstance(segment, int) else f"{out}.{segment}" if out else segment
    return out


def _byte_size(value: Any) -> Optional[int]:
    if isinstance(value, (bytes, bytearray)):
        return len(value)
    if isinstance(value, memoryview):
        return value.nbytes
    try:
        if value.seekable():
            position = value.tell()
            end = value.seek(0, 2)
            value.seek(position)
            return end - position
    except (AttributeError, OSError, ValueError):
        pass
    return None


def _is_upload_ref(value: Any) -> bool:
    return isinstance(value, dict) and len(value) == 1 and isinstance(value.get("$upload"), str)


def _check(schema: dict, value: Any, path: list, issues: list) -> Any:
    """Validates like the server's schema (same messages and paths) and returns the value with unknown object keys dropped."""

    def report(message: str) -> None:
        issues.append({"path": _format_path(path), "message": message})

    if not schema:
        return value
    if "anyOf" in schema:
        branches = [b for b in schema["anyOf"] if b.get("type") != "null"]
        if value is None and len(branches) < len(schema["anyOf"]):
            return None
        for branch in branches[1:]:
            trial: list = []
            result = _check(branch, value, path, trial)
            if not trial:
                return result
        return _check(branches[0], value, path, issues) if branches else report("expected null")
    kind, transfer = schema.get("type"), schema.get("x-apue-transfer")
    if kind == "null":
        if value is not None:
            report("expected no value")
        return None
    if kind == "boolean":
        if not isinstance(value, bool):
            report(f"expected boolean, got {_type_of(value)}")
        return value
    if kind in ("number", "integer"):
        if not isinstance(value, (int, float)) or isinstance(value, bool) or (isinstance(value, float) and not math.isfinite(value)):
            report(f"expected number, got {_type_of(value)}")
            return value
        if kind == "integer" and isinstance(value, float) and not value.is_integer():
            report("expected integer")
        if "minimum" in schema and value < schema["minimum"]:
            report(f"less than {_number(schema['minimum'])}")
        if "maximum" in schema and value > schema["maximum"]:
            report(f"greater than {_number(schema['maximum'])}")
        return value
    if kind == "string" and transfer in ("blob-frames", "upload"):
        if _is_upload_ref(value):
            return value
        readable = transfer == "upload" and callable(getattr(value, "read", None))
        size = _byte_size(value) if readable or isinstance(value, (bytes, bytearray, memoryview)) else None
        if size is None and not readable:
            report(f"expected {'a file' if transfer == 'upload' else 'bytes'}, got {_type_of(value)}")
        elif size is not None and "x-apue-max-size" in schema and size > schema["x-apue-max-size"]:
            report(f"more than {schema['x-apue-max-size']} bytes")
        return value
    if kind == "string" and "enum" in schema:
        if not isinstance(value, str) or value not in schema["enum"]:
            report(f"expected one of {', '.join(schema['enum'])}")
        return value
    if kind == "string":
        if not isinstance(value, str):
            report(f"expected string, got {_type_of(value)}")
            return value
        if "minLength" in schema and _utf16_length(value) < schema["minLength"]:
            report(f"shorter than {schema['minLength']}")
        if "maxLength" in schema and _utf16_length(value) > schema["maxLength"]:
            report(f"longer than {schema['maxLength']}")
        if "pattern" in schema:
            flags = schema.get("x-apue-flags", "")
            if not _pattern_ok(schema["pattern"], flags, value):
                report(f"does not match /{schema['pattern']}/{flags}")
        return value
    if kind == "array":
        if not isinstance(value, (list, tuple)):
            report(f"expected array, got {_type_of(value)}")
            return value
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            report(f"more than {schema['maxItems']} items")
            return value
        items = schema.get("items", {})
        out = []
        for index, item in enumerate(value):
            path.append(index)
            out.append(_check(items, item, path, issues))
            path.pop()
        return out
    if kind == "object" and transfer is None:
        if not isinstance(value, dict):
            report(f"expected object, got {_type_of(value)}")
            return value
        required = set(schema.get("required", []))
        result = {}
        for key, field in schema.get("properties", {}).items():
            path.append(key)
            if key not in value or value[key] is _ABSENT:
                if key in required:
                    report("required")
            else:
                result[key] = _check(field, value[key], path, issues)
            path.pop()
        return result  # unknown keys are dropped, like the server (and the TypeScript client) do
    return value


# ---- responses ----------------------------------------------------------------------------------

_CODING_ERRORS: tuple = (zlib.error, EOFError) + ((_zstd.ZstdError,) if _zstd is not None else ())


class _Decoder:
    """Incremental Content-Encoding decoder (gzip, deflate, zstd with compression.zstd)."""

    def __init__(self, coding: str):
        if coding not in ("gzip", "x-gzip", "deflate") and not (coding == "zstd" and _zstd is not None):
            raise _error(502, "Bad Gateway", f"unsupported content-coding {coding!r}")
        self.coding = coding
        self._raw_deflate = False
        self._started = False
        self._new()

    def _new(self) -> None:
        if self.coding == "zstd":
            self._d = _zstd.ZstdDecompressor()
        elif self.coding == "deflate":
            self._d = zlib.decompressobj(-zlib.MAX_WBITS if self._raw_deflate else zlib.MAX_WBITS)
        else:
            self._d = zlib.decompressobj(16 + zlib.MAX_WBITS)

    def feed(self, data: bytes) -> bytes:
        out = []
        while data:
            if self._d.eof:
                self._new()  # concatenated gzip members / zstd frames
            try:
                out.append(self._d.decompress(data))
            except _CODING_ERRORS as error:
                if self.coding == "deflate" and not self._started and not self._raw_deflate:
                    self._raw_deflate = True  # "deflate" without the zlib wrapper (seen in the wild)
                    self._new()
                    continue
                raise _malformed(f"undecodable {self.coding} body: {error}") from None
            self._started = True
            data = self._d.unused_data if self._d.eof else b""
        return b"".join(out)


class _Response:
    """An HTTP response whose body is read decoded (Content-Encoding) — incrementally for frames."""

    def __init__(self, raw: http.client.HTTPResponse):
        self.raw = raw
        self.status = raw.status
        self.coding = (raw.getheader("content-encoding") or "identity").strip().lower()
        self.type = (raw.getheader("content-type") or "").split(";")[0].strip().lower()
        self._decoder = None if self.coding in ("", "identity") else _Decoder(self.coding)
        self._buffer = bytearray()
        self._body: Optional[bytes] = None

    def header(self, name: str) -> Optional[str]:
        return self.raw.getheader(name)

    def _more(self) -> bool:
        chunk = self.raw.read1(BLOB_CHUNK)
        if not chunk:
            return False
        self._buffer += self._decoder.feed(chunk) if self._decoder else chunk
        return True

    def read(self) -> bytes:
        """The whole (decoded) body; may be called again."""
        if self._body is None:
            while self._more():
                pass
            self._body, self._buffer = bytes(self._buffer), bytearray()
        return self._body

    def chunks(self) -> Iterator[bytes]:
        while self._buffer or self._more():
            chunk, self._buffer = bytes(self._buffer), bytearray()
            if chunk:
                yield chunk

    def _exactly(self, n: int) -> bytes:
        while len(self._buffer) < n and self._more():
            pass
        out = bytes(self._buffer[:n])
        del self._buffer[:n]
        return out

    def frames(self) -> Iterator[tuple[int, int, int, bytes]]:
        """(type, flags, lane, payload) as each frame arrives."""
        while True:
            header = self._exactly(8)
            if not header:
                return
            if len(header) < 8:
                raise _malformed("stream ended inside a frame header")
            kind, flags, lane, length = struct.unpack(">BBHI", header)
            if length > MAX_FRAME:
                raise _malformed(f"frame payload {length} exceeds limit {MAX_FRAME}")
            payload = self._exactly(length) if length else b""
            if len(payload) < length:
                raise _malformed("stream ended inside a frame")
            yield kind, flags, lane, payload

    def finish(self) -> None:
        """Reads what is left of the body (after END: chunk terminator, coding trailer) so the connection stays usable."""
        try:
            while self.raw.read1(BLOB_CHUNK):
                pass
        except (OSError, http.client.HTTPException):
            pass

    @property
    def done(self) -> bool:
        return self.raw.isclosed()


def _problem(status: int, body: bytes) -> ApueError:
    try:
        problem = json.loads(body) if body else None
    except ValueError:
        problem = None
    return ApueError(status, problem if isinstance(problem, dict) else {"title": http.client.responses.get(status, "Error")})


def _json(body: bytes) -> Any:
    try:
        return json.loads(body)
    except ValueError as error:
        raise _error(502, "Bad Gateway", f"undecodable JSON: {error}") from None


def _retry_after(header: Optional[str]) -> Optional[float]:
    """Retry-After (RFC 9110 §10.2.3): delay-seconds or an HTTP-date; None if absent or invalid."""
    if header is None:
        return None
    value = header.strip()
    if value.isdigit():
        return float(value)
    try:
        when = email.utils.parsedate_to_datetime(value)
    except (TypeError, ValueError, IndexError):
        return None
    return max(0.0, when.timestamp() - time.time()) if when is not None else None


# ---- downloads ----------------------------------------------------------------------------------

class Download:
    """A t.download() output: `url` works as a plain link until `expires`; read() resumes and verifies."""

    def __init__(self, ref: dict, client: "ApueClientBase"):
        self.path: str = ref["$download"]
        self.url: str = client.base_url + self.path
        self.size: int = ref["size"]
        self.type: str = ref["type"]
        self.sha256: Optional[str] = ref.get("sha256")
        self.expires: str = ref["expires"]
        self._client = client

    def __repr__(self) -> str:
        return f"Download({self.url!r}, size={self.size}, type={self.type!r})"

    def stream(self) -> Iterator[bytes]:
        received, etag, failures = 0, None, 0
        digest = hashlib.sha256()
        while received < self.size or self.size == 0:
            # Ranges count bytes of the representation: no content-coding here.
            headers = {"accept-encoding": "identity"}
            if received:
                headers["range"] = f"bytes={received}-"
                if etag:
                    headers["if-range"] = etag
            try:
                res = self._client._request("GET", self.path, headers, None)
                if res.status >= 400:
                    raise _problem(res.status, res.read())
                skip = 0
                if received == 0:
                    etag = res.header("etag")
                elif res.status == 206:
                    if not (res.header("content-range") or "").startswith(f"bytes {received}-"):
                        raise ApueError(502, {"title": "Bad Gateway", "detail": "download resumed at the wrong offset"})
                elif res.status == 200 and etag and res.header("etag") == etag:
                    skip = received
                else:
                    raise ApueError(502, {"title": "Bad Gateway", "detail": "the download changed while resuming"})
                for chunk in res.chunks():
                    if skip:
                        cut = min(skip, len(chunk))
                        chunk, skip = chunk[cut:], skip - cut
                        if not chunk:
                            continue
                    if received + len(chunk) > self.size:
                        raise ApueError(502, {"title": "Bad Gateway", "detail": "download larger than announced"})
                    received += len(chunk)
                    digest.update(chunk)
                    yield chunk
                if self.size == 0 or received == self.size:
                    break
                raise ConnectionError(f"download ended after {received} of {self.size} bytes")
            except (OSError, http.client.HTTPException) as error:
                failures += 1
                self._client._drop()
                if failures > self._client.retries:
                    raise error
                time.sleep(self._client._backoff(failures))
        if self.sha256 is not None and digest.hexdigest() != self.sha256:
            raise ApueError(502, {"title": "Bad Gateway", "detail": "download content does not match its SHA-256"})

    def read(self) -> bytes:
        return b"".join(self.stream())


Uploadable = Union[bytes, bytearray, memoryview, BinaryIO]


# ---- batches ------------------------------------------------------------------------------------

_FORBIDDEN_SEGMENTS = ("__proto__", "constructor", "prototype")


class Ref:
    """The output of an earlier call in a batch (or a field of it), as part of a later call's input."""

    __slots__ = ("lane", "path")

    def __init__(self, lane: int, path: tuple):
        self.lane, self.path = lane, path

    def __repr__(self) -> str:
        return f"Ref({self.lane}, {list(self.path)!r})"


def _encode_args(value: Any) -> Any:
    """Ref → {"$ref": [lane, …path]}; data that looks like a reference is escaped as {"$lit": …}."""
    if isinstance(value, Ref):
        return {"$ref": [value.lane, *value.path]}
    if isinstance(value, (list, tuple)):
        return [_encode_args(x) for x in value]
    if isinstance(value, dict):
        if len(value) == 1 and next(iter(value)) in ("$ref", "$lit"):
            return {"$lit": value}
        return {k: _encode_args(x) for k, x in value.items()}
    return value


def _refs(value: Any) -> list:
    if isinstance(value, Ref):
        return [value.lane]
    if isinstance(value, (list, tuple)):
        return [lane for x in value for lane in _refs(x)]
    if isinstance(value, dict):
        return [lane for x in value.values() for lane in _refs(x)]
    return []


class BatchCall(Generic[T]):
    """A unary call in a batch. After `send()`: `result()` returns its output or raises its problem."""

    def __init__(self, lane: int):
        self.lane = lane
        self.done = False
        self.error: Optional[ApueError] = None
        self._value: Any = None

    def ref(self, *path: Union[str, int]) -> Any:
        """A reference to this call's output (or a field of it: `ref("user", "id")`, indices as ints)."""
        for segment in path:
            if isinstance(segment, bool) or not (isinstance(segment, str) or (isinstance(segment, int) and segment >= 0)):
                raise TypeError("ref path segments are strings or non-negative integers")
            if segment in _FORBIDDEN_SEGMENTS:
                raise ValueError(f"ref path segment {segment} is not allowed")
        return Ref(self.lane, path)

    def result(self) -> T:
        if not self.done:
            raise RuntimeError("the batch has not been sent")
        if self.error is not None:
            raise self.error
        return self._value

    def _msg(self, value: Any) -> None:
        self._value = value

    def _end(self, info: dict) -> None:
        if info.get("status", 200) >= 400:
            self.error = ApueError(info["status"], info.get("problem"))
        self.done = True

    def _fail(self, error: ApueError) -> None:
        if not self.done:
            self.error, self.done = error, True


class BatchStream(Generic[T]):
    """A server-streaming call in a batch: after `send()`, iterating yields its items (then raises its problem, if any)."""

    def __init__(self, lane: int):
        self.lane = lane
        self.done = False
        self.error: Optional[ApueError] = None
        self.items: list = []

    def __iter__(self) -> Iterator[T]:
        if not self.done:
            raise RuntimeError("the batch has not been sent")
        yield from self.items
        if self.error is not None:
            raise self.error

    def _msg(self, value: Any) -> None:
        self.items.append(value)

    _end = BatchCall._end
    _fail = BatchCall._fail


class ApueBatchBase:
    """Pipelined batch (SPEC-DRAFT §10): dependent calls in one round trip; one lane per call."""

    def __init__(self, client: "ApueClientBase"):
        self._client = client
        self._entries: list = []  # (op name, op, input, sink, key)
        self._sent = False

    def call(self, name: str, input: Any = _ABSENT, *, idempotency_key: Optional[str] = None) -> BatchCall:
        return self._add(name, input, BatchCall(len(self._entries)), "none", idempotency_key)

    def stream(self, name: str, input: Any = _ABSENT) -> BatchStream:
        return self._add(name, input, BatchStream(len(self._entries)), "server", None)

    def _add(self, name: str, value: Any, sink: Any, stream: str, key: Optional[str]) -> Any:
        if self._sent:
            raise RuntimeError("batch already sent")
        op = self._client.OPS.get(name)
        if op is None:
            raise _error(404, "Unknown Operation", name, "unknown-operation")
        if op["stream"] != stream:
            raise ValueError(f"{name} is not a {'unary' if stream == 'none' else 'server-streaming'} operation")
        for lane in _refs(value):
            if lane >= sink.lane:
                raise ValueError(f"ref to call {lane} must come from an earlier call in this batch")
        # Inputs containing refs can only be validated on the server, after resolution.
        if value is not _ABSENT and not _refs(value):
            value = self._client._validated(op, value, f"input of call {sink.lane}")
        if op["effect"] != "safe":
            key = key or str(uuid.uuid4())  # keyed calls make the whole batch safe to resend
        self._entries.append((name, op, value, sink, key))
        return sink

    def send(self, *, timeout_ms: Optional[int] = None) -> None:
        """Sends every call in one request and reads every lane. A failed call fails only its own lane
        (and, with 424, the calls that depend on it); `send` raises only if the batch as a whole fails."""
        if self._sent:
            raise RuntimeError("batch already sent")
        if not self._entries:
            raise ValueError("batch is empty")
        self._sent = True
        client, created, uploaded = self._client, [], {}
        sinks = [entry[3] for entry in self._entries]
        try:
            calls = []
            for name, op, value, _sink, key in self._entries:
                call: dict = {"op": name}
                if value is not _ABSENT:
                    call["in"] = _encode_args(client._with_uploads(op["input"], value, created, uploaded))
                if key is not None:
                    call["key"] = key
                calls.append(call)
            headers = {"accept": ACCEPT, "content-type": "application/json"}
            if timeout_ms is not None:
                headers["apue-timeout"] = str(int(timeout_ms))
            safe = all(op["effect"] == "safe" for _n, op, *_rest in self._entries)
            method = "QUERY" if safe and client._query_ok else "POST"
            res = client._send(method, "/$batch", headers, canonical_json({"calls": calls}).encode(), True)
            try:
                if res.status != 200 or res.type != STREAM_JSON:
                    raise _problem(res.status if res.status >= 400 else 502, res.read())
                self._read(res)
            finally:
                if not res.done:
                    client._drop()
        except (OSError, http.client.HTTPException) as error:
            failure = _error(502, "Bad Gateway", f"batch failed: {error}")
            for sink in sinks:
                sink._fail(failure)
            raise
        except ApueError as error:
            for sink in sinks:
                sink._fail(error)
            raise
        finally:
            client._delete_uploads(created)

    def _read(self, res: _Response) -> None:
        open_lanes = set(range(len(self._entries)))
        blobs: dict = {}
        for kind, flags, lane, payload in res.frames():
            if lane not in open_lanes:
                continue
            _name, op, _value, sink, _key = self._entries[lane]
            bytes_out = _transfers(op["output"], "blob-frames")
            if kind == BLOB:
                if not bytes_out:
                    raise _malformed("BLOB frame for an op without bytes")
                blobs.setdefault(lane, _Blobs()).push(flags, payload)
            elif kind == MSG:
                value = _json(payload)
                if bytes_out:
                    value = blobs.setdefault(lane, _Blobs()).resolve(value)
                sink._msg(self._client._outputs(op, value))
            elif kind == END:
                sink._end(_json(payload))
                open_lanes.discard(lane)
                if not open_lanes:
                    res.finish()
                    return
        error = _error(502, "Truncated Stream", f"lanes {', '.join(map(str, sorted(open_lanes)))} ended without END frame", "truncated-stream")
        for lane in open_lanes:
            self._entries[lane][3]._fail(error)


# ---- the client ---------------------------------------------------------------------------------

class ApueClientBase:
    """Calls an apü API. `OPS` is the API's operations (from the manifest), embedded by the generator."""

    OPS: dict = {}

    def __init__(self, base_url: str, *, cafile: Optional[str] = None, context: Optional[ssl.SSLContext] = None,
                 authorization: Optional[str] = None, retries: int = 2, backoff: float = 0.1, max_backoff: float = 2.0,
                 timeout: float = 60, resumes: int = 3, accept_encoding: Optional[str] = None, validate: bool = True):
        """`resumes`: how often a resumable stream is resumed after lost connections. `accept_encoding`:
        the codings offered for responses (default: zstd where available, gzip; "identity" for none).
        `validate`: check inputs against the op's schema before sending (the server checks them too)."""
        parsed = urllib.parse.urlsplit(base_url)
        if parsed.scheme != "https":
            raise ValueError("apü servers speak HTTPS")
        self.base_url = base_url.rstrip("/")
        self._host, self._port = parsed.hostname, parsed.port or 443
        self._context = context or ssl.create_default_context(cafile=cafile)
        self._timeout = timeout
        self.authorization = authorization
        self.retries, self.backoff = retries, backoff
        self._max_backoff, self._resumes = max_backoff, resumes
        self._accept_encoding = accept_encoding or ACCEPT_ENCODING
        self._validate = validate
        self._query_ok = True
        self._conn: Optional[http.client.HTTPSConnection] = None
        self._last: Optional[_Response] = None

    def close(self) -> None:
        self._drop()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def batch(self) -> ApueBatchBase:
        return ApueBatchBase(self)

    def _drop(self) -> None:
        if self._conn is not None:
            self._conn.close()
            self._conn = None
        self._last = None

    def _backoff(self, attempt: int) -> float:
        return random.random() * min(self._max_backoff, self.backoff * 2**attempt)

    def _request(self, method: str, path: str, headers: dict, body) -> _Response:
        if self._last is not None and not self._last.done:
            self._drop()  # an unread response would be taken for this request's
        if self._conn is None:
            self._conn = http.client.HTTPSConnection(self._host, self._port, context=self._context, timeout=self._timeout)
        all_headers = {"accept-encoding": self._accept_encoding, **headers}
        if self.authorization is not None:
            all_headers["authorization"] = self.authorization
        chunked = body is not None and not isinstance(body, (bytes, bytearray))
        self._conn.request(method, path, body=body, headers=all_headers, encode_chunked=chunked)
        raw = self._conn.getresponse()
        try:
            self._last = _Response(raw)
        except ApueError:
            self._drop()  # e.g. an unsupported content-coding: the body can't be read
            raise
        return self._last

    def _send(self, method: str, path: str, headers: dict, body, retry: bool) -> _Response:
        """Sends with QUERY → POST fallback and, if `retry`, retries (connection loss, 429/503, retryable 409)."""
        attempt, query_rejected = 0, None
        while True:
            try:
                res = self._request(method, path, headers, body)
            except (OSError, http.client.HTTPException):
                self._drop()
                if not retry or attempt >= self.retries:
                    raise
                attempt += 1
                time.sleep(self._backoff(attempt))
                continue
            if method == "QUERY" and res.status in QUERY_REJECTED:
                res.read()
                query_rejected, method = res.status, "POST"  # a method fallback is not a retry
                continue
            if query_rejected is not None and res.status != query_rejected:
                self._query_ok = False  # remembered only if POST fares better
            if retry and attempt < self.retries:
                delay = self._retry_delay(res, attempt)
                if delay is not None:
                    attempt += 1
                    time.sleep(delay)
                    continue
            return res

    def _retry_delay(self, res: _Response, attempt: int) -> Optional[float]:
        if res.status in (429, 503):
            res.read()
            delay = _retry_after(res.header("retry-after"))
            return self._backoff(attempt) if delay is None else min(delay, self._max_backoff)
        if res.status == 409 and res.type == "application/problem+json":
            problem = _problem(409, res.read())  # buffered: the caller can still read it
            if problem.retryable:
                return self._backoff(attempt)
        return None

    def _validated(self, op: dict, value: Any, what: str) -> Any:
        if not self._validate or value is _ABSENT:
            return value
        issues: list = []
        value = _check(op["input"], value, [], issues)
        if issues:
            raise ApueError(400, {"type": PROBLEMS + "validation-failed", "title": "Validation Failed", "status": 400,
                                  "detail": f"{what} does not match the schema", "fields": issues})
        return value

    # -- uploads (bytes and file inputs) -------------------------------------------------------

    def upload(self, data: Uploadable) -> dict:
        """Uploads content to /$uploads in one request and returns its reference {"$upload": id}."""
        body = bytes(data) if isinstance(data, (bytes, bytearray, memoryview)) else iter(lambda: data.read(BLOB_CHUNK), b"")
        res = self._request("POST", "/$uploads", {"upload-complete": "?1", "content-type": "application/octet-stream"}, body)
        payload = res.read()
        if res.status != 201:
            raise _problem(res.status, payload)
        return {"$upload": _json(payload)["upload"]}

    def delete_upload(self, ref: dict) -> None:
        self._request("DELETE", f"/$uploads/{ref['$upload']}", {}, None).read()

    def _delete_uploads(self, created: list) -> None:
        for ref in created:
            try:
                self.delete_upload(ref)
            except (OSError, http.client.HTTPException):
                self._drop()

    def _with_uploads(self, schema: dict, value: Any, created: list, uploaded: Optional[dict] = None) -> Any:
        uploaded = {} if uploaded is None else uploaded  # one buffer in several places (or batch calls): one upload

        def replace(v: Any, _kind: str) -> Any:
            if _is_upload_ref(v) or isinstance(v, Ref):
                return v
            if id(v) not in uploaded:
                uploaded[id(v)] = (self.upload(v), v)
                created.append(uploaded[id(v)][0])
            return uploaded[id(v)][0]

        return _map(schema, value, ("blob-frames", "upload"), replace) if _transfers(schema, "blob-frames|upload") else value

    def _outputs(self, op: dict, value: Any) -> Any:
        schema = op["output"]
        if not _transfers(schema, "download"):
            return value
        return _map(schema, value, ("download",), lambda ref, _k: Download(ref, self))

    # -- calls ----------------------------------------------------------------------------------

    def _prepare(self, name: str, op: dict, value: Any, timeout_ms: Optional[int], key: Optional[str],
                 resume: Optional[str] = None) -> tuple[str, str, dict, Optional[bytes]]:
        headers = {"accept": ACCEPT}
        if timeout_ms is not None:
            headers["apue-timeout"] = str(int(timeout_ms))
        if resume is not None:
            headers["apue-resume"] = resume
        read = op["effect"] == "safe" and op["stream"] in ("none", "server")
        if read:
            path = f"/{name}" if value is _ABSENT else f"/{name}?i={urllib.parse.quote(canonical_json(value), safe='')}"
            if len(path) <= MAX_GET_URL:
                return "GET", path, headers, None
        body = None if value is _ABSENT else canonical_json(value).encode()
        if body is not None:
            headers["content-type"] = "application/json"
        if op["effect"] != "safe" and op["stream"] == "none":
            headers["idempotency-key"] = '"' + (key or str(uuid.uuid4())) + '"'
        return ("QUERY" if read and self._query_ok else "POST"), f"/{name}", headers, body

    def _events(self, op: dict, res: _Response) -> Iterator[tuple[int, Any]]:
        """(MSG, value) for each output and (CHECKPOINT, token) for each resume token; raises END errors."""
        if res.status >= 400 or res.type != STREAM_JSON:
            body = res.read()
            if res.status >= 400 or res.type == "application/problem+json":
                raise _problem(res.status, body)
            if res.type != "application/json":
                raise _error(502, "Unexpected Content-Type", res.type or "(none)")
            yield MSG, self._outputs(op, _json(body))
            return
        blobs = _Blobs() if _transfers(op["output"], "blob-frames") else None
        for kind, flags, _lane, payload in res.frames():
            if kind == BLOB:
                if blobs is None:
                    raise _malformed("BLOB frame for an op without bytes")
                blobs.push(flags, payload)
            elif kind == MSG:
                value = _json(payload)
                yield MSG, self._outputs(op, blobs.resolve(value) if blobs else value)
            elif kind == CHECKPOINT:
                yield CHECKPOINT, payload.decode()
            elif kind == END:
                info = _json(payload)
                res.finish()
                if info.get("status", 200) >= 400:
                    raise ApueError(info["status"], info.get("problem"))
                return
            # HEARTBEAT and unknown frame types are ignored.
        raise _error(502, "Truncated Stream", "response ended without END frame", "truncated-stream", _Truncated)

    def _call(self, name: str, value: Any = _ABSENT, *, timeout_ms: Optional[int] = None, idempotency_key: Optional[str] = None) -> Any:
        op = self.OPS[name]
        value = self._validated(op, value, "input")
        created: list = []
        try:
            value = self._with_uploads(op["input"], value, created) if value is not _ABSENT else value
            method, path, headers, body = self._prepare(name, op, value, timeout_ms, idempotency_key)
            retry = op["effect"] != "unsafe" or "idempotency-key" in headers
            res = self._send(method, path, headers, body, retry)
            values = [v for kind, v in self._events(op, res) if kind == MSG]
            return values[0] if values else None
        finally:
            self._delete_uploads(created)

    def _stream(self, name: str, value: Any = _ABSENT, *, timeout_ms: Optional[int] = None) -> Iterator[Any]:
        op = self.OPS[name]
        value = self._validated(op, value, "input")
        created: list = []
        try:
            value = self._with_uploads(op["input"], value, created) if value is not _ABSENT else value
            token: Optional[str] = None
            resumes = 0
            # Messages received after the last checkpoint are sent again on resume (the server replays
            # from the cursor): skip exactly that many, so the consumer sees every item once.
            since_checkpoint = skip = 0
            while True:
                method, path, headers, body = self._prepare(name, op, value, timeout_ms, None, token)
                res = self._send(method, path, headers, body, op["effect"] != "unsafe")
                try:
                    for kind, item in self._events(op, res):
                        if kind == CHECKPOINT:
                            token, since_checkpoint, skip = item, 0, 0
                            continue
                        since_checkpoint += 1
                        if skip:
                            skip -= 1
                            continue
                        yield item
                    return
                except (OSError, http.client.HTTPException, _Truncated):
                    # Resume only after a lost connection (not after an END error, not for malformed
                    # frames), only with a checkpoint, and within the budget.
                    self._drop()
                    if not op.get("resumable") or token is None or resumes >= self._resumes:
                        raise
                    # Skipped-but-not-yet-replayed items still count: a loss during the replay must
                    # not shrink the window of items the consumer has already seen.
                    skip += since_checkpoint
                    since_checkpoint = 0
                    resumes += 1
                    time.sleep(self._backoff(resumes - 1))
                finally:
                    if not res.done:
                        self._drop()  # abandoned mid-stream: the connection can't be reused
        finally:
            self._delete_uploads(created)

    def _client_stream(self, name: str, inputs: Iterable[Any], *, timeout_ms: Optional[int] = None) -> Iterator[Any]:
        op = self.OPS[name]
        bytes_in = _transfers(op["input"], "blob-frames")

        def body() -> Iterator[bytes]:
            for index, item in enumerate(inputs):
                item = self._validated(op, item, f"input message {index}")
                if bytes_in:
                    yield b"".join(_message_frames(item))
                else:
                    yield _frame(MSG, json.dumps(item, separators=(",", ":"), ensure_ascii=False).encode())
            yield _frame(END, json.dumps({"status": 200}).encode())

        # RFC 10036 §3: `incremental` on the request too, or intermediaries may buffer the upload.
        headers = {"accept": ACCEPT, "content-type": STREAM_JSON, "incremental": "?1"}
        if timeout_ms is not None:
            headers["apue-timeout"] = str(int(timeout_ms))
        try:
            res = self._request("POST", f"/{name}", headers, body())
        except BaseException:
            self._drop()  # the request body is incomplete (an invalid input, or the connection failed)
            raise
        try:
            for kind, item in self._events(op, res):
                if kind == MSG:
                    yield item
        finally:
            if not res.done:
                self._drop()
